    input.orgId,
    input.body,
    [],
    comment.authorId,
  );
  const previouslyMentioned = new Set(comment.mentionedUserIds);
  const newlyMentionedUserIds = mentionedUserIds.filter(
    (userId) => !previouslyMentioned.has(userId),
  );

  const updated = await commentRepo.updateComment(input, mentionedUserIds);

