async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members = await listAllActiveMembers(orgId);

  const resolved = resolveMentions(body, members);
  const known = new Set(members.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ].filter((id) => id !== authorId);
}

/**
 * Every active member of the org, paged through in full — mention resolution
 * must see the whole roster, not just whatever fits on the first page.
 */
async function listAllActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }

  return members;
}

