    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: [...descendantsOf(comment.id)].sort((a, b) =>
        a.createdAt === b.createdAt
          ? a.id.localeCompare(b.id)
          : a.createdAt.localeCompare(b.createdAt),
